import {TYPES,METHODS,cents,totals,validate,csvCell} from './core.js';
const $=s=>document.querySelector(s), fmt=n=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:n%100?2:0}).format(n/100), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localDate=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const KEY='shina-tetrad-v1';let data={version:1,entries:[],days:{}},storageError=false;
try{const saved=localStorage.getItem(KEY);if(saved)data=validate(JSON.parse(saved));}catch{storageError=true;}
let date=localDate(),filter='Все',page='journal',editing=null,dayMode='opening';$('#date').value=date;
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000);}
// Save the proposed state first: a full disk must never look like a successful write.
function commit(next){try{if(storageError)throw Error('Данные в браузере не удалось прочитать. Сначала сохраните исходную копию через поддержку.');validate(next);localStorage.setItem(KEY,JSON.stringify(next));data=next;return true;}catch(e){toast('Не сохранено: '+e.message);return false;}}
function day(){return data.days[date]||{opening:0,actual:null,closed:false};}function entries(){return data.entries.filter(e=>e.date===date);}
function withDay(){const n=structuredClone(data);n.days[date]??={opening:0,actual:null,closed:false};return n;}
const symbol=t=>({sale:'↗',service:'✳',straightening:'◉',package:'▱',disposal:'↻',purchase:'↓',expense:'−',salary:'−',collection:'↗',refund:'↩',market:'↩',income:'＋',other:'↗',bonus:'−'}[t]);
function render(){const d=day(),es=entries(),t=totals(es,d.opening);$('#balance').textContent=fmt(t.ending);$('#opening-label').textContent=fmt(d.opening);$('#revenue').textContent=fmt(t.revenue);$('#outflow').textContent=fmt(t.outflow);$('#count').textContent=es.length;$('#day-state').textContent=d.closed?'Закрыт':'Открыт';$('#day-state').classList.toggle('closed',d.closed);$('#opening').disabled=d.closed;$('#add-top').disabled=d.closed;
 $('#filters').innerHTML=['Все','Продажи','Услуги','Расходы','Закупки','Возвраты','Касса'].map(f=>`<button class="${f===filter?'active':''}" data-filter="${f}">${f}</button>`).join('');
 const query=$('#search').value.toLocaleLowerCase('ru');const rows=es.filter(e=>(filter==='Все'||TYPES[e.type][2]===filter)&&[e.title,e.article,e.customer,e.phone,e.manager,e.note].join(' ').toLocaleLowerCase('ru').includes(query)).sort((a,b)=>b.time.localeCompare(a.time)||b.id.localeCompare(a.id));
 $('#entries').innerHTML=rows.length?rows.map(e=>`<button class="entry ${TYPES[e.type][1]<0?'out':''}" data-id="${esc(e.id)}" aria-label="Открыть запись: ${esc(e.title)}"><span class="entry-symbol">${symbol(e.type)}</span><span class="entry-body"><span class="entry-title">${esc(e.title)}</span><span class="entry-meta" style="display:block">${esc(TYPES[e.type][0])} · ${e.qty} шт.${e.manager?' · '+esc(e.manager):''}<br>${e.payments.map(p=>esc(METHODS[p.method])).join(' + ')}${e.customer?' · '+esc(e.customer):''}</span></span><span class="entry-right"><span class="entry-amount">${TYPES[e.type][1]<0?'−':''}${fmt(e.amount)}</span><span class="entry-time" style="display:block">${e.time}</span></span></button>`).join(''):`<div class="empty"><div class="empty-icon">▤</div><h3>${es.length?'Ничего не найдено':'Чистая страница вашего дня'}</h3><p>${es.length?'Измените поиск или выберите другой раздел.':'Добавьте первую продажу или услугу. Тетрадь сама посчитает выручку и остаток кассы.'}</p>${!es.length&&!d.closed?'<button class="primary" id="empty-add">＋ Первая запись</button>':''}</div>`;
 const row=(a,b,cls='')=>`<div class="summary-row ${cls}"><span>${a}</span><b>${fmt(b)}</b></div>`;
 $('#summary').innerHTML=`<div class="summary-block"><h3>ВЫРУЧКА · ВСЕ СПОСОБЫ ОПЛАТЫ</h3>${row('Продажи, пакеты, прочее',t.sales)}${row('Шиномонтаж, правка, утилизация',t.services)}${row('Выручка до возвратов',t.revenue,'total')}${row('Возвраты покупателям и Я.Маркет',t.refunds)}${row('Выручка за вычетом возвратов',t.revenue-t.refunds)}</div><div class="summary-block"><h3>ДВИЖЕНИЕ НАЛИЧНЫХ</h3>${row('На начало дня',d.opening)}${row('+ Все поступления наличными',t.cashIn)}${row('− Все выплаты наличными',t.cashOut)}${row('Расчетный остаток',t.ending,'total')}${d.actual!==null?row('Фактически в кассе',d.actual)+row('Расхождение: факт − расчет',d.actual-t.ending):''}</div><div class="summary-block"><h3>БЕЗНАЛИЧНЫЕ · ПОСТУПЛЕНИЯ МИНУС ВЫПЛАТЫ</h3>${row('QR',t.qr)}${row('Терминал',t.card)}${row('Перевод',t.transfer)}</div>`;$('#close-day').textContent=d.closed?'Открыть день для исправлений':'Закрыть день и сверить кассу';
 $('#titles').innerHTML=[...new Set(data.entries.map(e=>e.title))].slice(-100).map(s=>`<option value="${esc(s)}">`).join('');$('#managers').innerHTML=[...new Set(data.entries.map(e=>e.manager).filter(Boolean))].map(s=>`<option value="${esc(s)}">`).join('');
}
function go(p){page=p;for(const s of ['journal','summary','data'])$('#'+s+'-view').hidden=s!==p;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));$('#page-title').textContent={journal:'Рабочий день',summary:'Итоги смены',data:'Моя тетрадь'}[p];render();}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#settings').onclick=()=>go('data');$('#send-sheet').onclick=()=>toast('Подключение Google Таблицы скоро. Данные не отправлены.');
$('#date').onchange=()=>{if(!$('#date').value)return;date=$('#date').value;render();};for(const [id,delta]of [['prev',-1],['next',1]])$('#'+id).onclick=()=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+delta);date=localDate(d);$('#date').value=date;render();};$('#today').onclick=()=>{date=localDate();$('#date').value=date;render();};
$('#filters').onclick=e=>{if(e.target.dataset.filter){filter=e.target.dataset.filter;render();}};$('#search').oninput=render;
$('#type').innerHTML=Object.entries(TYPES).map(([k,v])=>`<option value="${k}">${v[0]}</option>`).join('');
const form=$('#entry-form');const field=k=>form.elements.namedItem(k);function mixed(){$('#mixed-fields').hidden=field('payment').value!=='mixed';}$('#payment').onchange=mixed;
function openEditor(id=null){if(day().closed){toast('День закрыт. Откройте его в разделе «Итог дня».');return;}editing=id;form.reset();$('#form-error').textContent='';$('#extra').open=false;$('#editor-title').textContent=id?'Изменить запись':'Новая запись';$('#delete').hidden=!id;
 if(id){const e=data.entries.find(e=>e.id===id);for(const k of ['type','title','qty','manager','time','article','customer','phone','note'])field(k).value=e[k];field('amount').value=(e.amount/100).toFixed(2);if(e.payments.length===1)field('payment').value=e.payments[0].method;else{field('payment').value='mixed';field('cashPart').value=((e.payments.find(p=>p.method==='cash')?.amount||0)/100).toFixed(2);field('secondMethod').value=e.payments.find(p=>p.method!=='cash')?.method||'qr';}$('#extra').open=!!(e.article||e.customer||e.phone||e.note);}
 else field('time').value=new Date().toTimeString().slice(0,5);mixed();$('#editor').showModal();}
$('#add-top').onclick=()=>openEditor();$('#add-nav').onclick=()=>openEditor();$('#entries').onclick=e=>{const b=e.target.closest('[data-id]');if(b)openEditor(b.dataset.id);if(e.target.closest('#empty-add'))openEditor();};$('.dismiss').onclick=()=>$('#editor').close();
form.onsubmit=e=>{e.preventDefault();try{if(day().closed)throw Error('День закрыт');const amount=cents(field('amount').value);if(!amount)throw Error('Сумма должна быть больше нуля');let payments=[{method:field('payment').value,amount}];if(field('payment').value==='mixed'){const cash=cents(field('cashPart').value);if(cash<=0||cash>=amount)throw Error('Наличная часть должна быть больше нуля и меньше общей суммы');payments=[{method:'cash',amount:cash},{method:field('secondMethod').value,amount:amount-cash}];}const n=withDay();const item={id:editing||crypto.randomUUID(),date,amount,payments};for(const k of ['type','title','manager','time','article','customer','phone','note'])item[k]=field(k).value.trim();item.qty=Number(field('qty').value);if(!item.title)throw Error('Введите наименование');if(editing)n.entries=n.entries.map(x=>x.id===editing?item:x);else n.entries.push(item);if(commit(n)){$('#editor').close();render();toast('Запись сохранена');}}catch(err){$('#form-error').textContent=err.message;}};
$('#delete').onclick=()=>{if(!confirm('Удалить эту запись?'))return;const n=withDay();n.entries=n.entries.filter(e=>e.id!==editing);if(commit(n)){$('#editor').close();render();toast('Запись удалена');}};
function openDay(mode){dayMode=mode;$('#day-error').textContent='';$('#day-title').textContent=mode==='opening'?'Наличные на начало дня':'Закрытие дня';$('#day-description').textContent=mode==='opening'?'Укажите фактический остаток на начало смены. Он не считается выручкой.':'Пересчитайте наличные и введите фактическую сумму. После закрытия записи защищены от изменений.';$('#day-value').value=mode==='opening'?(day().opening/100).toFixed(2):'';if(mode==='opening'&&!data.days[date]){const prev=Object.keys(data.days).filter(x=>x<date&&data.days[x].closed).sort().at(-1);if(prev){const pd=data.days[prev];$('#day-value').value=((pd.actual??totals(data.entries.filter(e=>e.date===prev),pd.opening).ending)/100).toFixed(2);$('#day-description').textContent+=' Предложен остаток последнего закрытого дня — проверьте его.';}}$('#day-dialog').showModal();}
$('#opening').onclick=()=>openDay('opening');$('#day-dismiss').onclick=()=>$('#day-dialog').close();$('#close-day').onclick=()=>{if(day().closed){if(confirm('Открыть день для исправлений? Сверку кассы потребуется выполнить заново.')){const n=withDay();n.days[date].closed=false;n.days[date].actual=null;if(commit(n)){render();toast('День открыт');}}}else openDay('close');};
$('#day-form').onsubmit=e=>{e.preventDefault();try{const v=cents($('#day-value').value),n=withDay();if(dayMode==='opening')n.days[date].opening=v;else{n.days[date].actual=v;n.days[date].closed=true;}if(commit(n)){$('#day-dialog').close();render();toast(dayMode==='opening'?'Начальный остаток сохранен':'День закрыт');}}catch(err){$('#day-error').textContent=err.message;}};
function download(content,name,type){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);}
$('#backup').onclick=()=>download(JSON.stringify(data,null,2),'тетрадь-копия-'+localDate()+'.json','application/json');
$('#csv').onclick=()=>{const rows=[['Дата','Время','Операция','Наименование','Артикул','Количество','Сумма, руб.','Направление','Наличные, руб.','QR, руб.','Терминал, руб.','Перевод, руб.','Сотрудник','Клиент','Телефон','Примечание']];for(const e of entries().sort((a,b)=>a.time.localeCompare(b.time)))rows.push([e.date,e.time,TYPES[e.type][0],e.title,e.article,e.qty,(e.amount/100).toFixed(2).replace('.',','),TYPES[e.type][1]>0?'Приход':'Расход',...Object.keys(METHODS).map(m=>(e.payments.filter(p=>p.method===m).reduce((s,p)=>s+p.amount,0)/100).toFixed(2).replace('.',',')),e.manager,e.customer,e.phone,e.note]);download('\ufeff'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'тетрадь-'+date+'.csv','text/csv;charset=utf-8');};
$('#restore').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>10e6)throw Error('Файл больше 10 МБ');const n=validate(JSON.parse(await f.text()));if(confirm(`Заменить все текущие данные копией: ${n.entries.length} записей? Сначала сохраните текущую резервную копию.`)&&commit(n)){render();toast('Данные восстановлены');}}catch(err){toast('Копия не загружена: '+err.message);}e.target.value='';};
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install').hidden=false;});$('#install').onclick=async()=>{await installPrompt?.prompt();$('#install').hidden=true;};
window.addEventListener('storage',e=>{if(e.key===KEY){try{data=validate(JSON.parse(e.newValue));render();toast('Данные обновлены в другой вкладке');}catch{toast('Изменились данные браузера. Перезагрузите приложение.');}}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});render();if(storageError)toast('Ошибка чтения данных. Новые записи заблокированы, чтобы сохранить исходные данные.');
